        const gateResult = RequirementTestGateResult.fromJSON(attached.payload);
        const specId = ctx.specId ?? ctx.flowState.specId;
        const state = ctx.flowManager.canonicalState(specId);
        const store = new RequirementTestArtifactStore({ flowManager: ctx.flowManager, state });
        const planRead = store.readPlan("test-gate");
        const workItem = planRead.artifact.plan.activeWorkItem();
        const candidateRead = store.readCandidate({ bundle: workItem.bundleRevision, consumerNodeId: "test-gate" });
        const facts = new RequirementTestLifecycleFacts({
          authority: RequirementTestLifecycleAuthority.capture({ state, planDescriptor: planRead.descriptor }),
          plan: planRead.artifact.plan,
          leaf: "test-gate",
          observation: gateResult.observation,
          candidateBundle: candidateRead.candidate,
        });
        const decision = resolveRequirementTestLifecycle(facts);
        let deferredReceipt = null;
        let findingsPublication = null;
        let failureArtifact = null;
        if (decision.disposition === "defer") {
          const fingerprints = new Set(gateResult.findings.map((finding) => finding.fingerprint));
          failureArtifact = new RequirementTestFailureArtifact({
            requirementId: workItem.requirementId,
            bundleRevision: workItem.bundleRevision.revision,
            fingerprint: gateResult.findings[0].fingerprint,
          });
          const sourceArtifact = failureArtifact.relativePath;
          findingsPublication = buildDeferredSemanticFindingsPublication({
            flowManager: ctx.flowManager,
            flowState: ctx.flowManager.loadReadOnly(specId),
            nodeId: "test-gate",
            sourceStep: "test-gate",
            sourceArtifact,
            sourcePayload: gateResult.toJSON(),
            sourceRelativePath: sourceArtifact,
            attempts: workItem.budget.autoSemantic + workItem.budget.manualSemantic + workItem.budget.tooling + 1,
            fingerprints,
          });
          deferredReceipt = new RequirementTestDeferredReceipt({
            requirementId: workItem.requirementId,
            specRevision: workItem.specRevision,
            bundleRevision: workItem.bundleRevision.revision,
            candidateDigest: candidateRead.candidate.digest,
            expectation: workItem.expectation,
            budget: workItem.budget,
            sourceAttempt: { id: state.attempt.id, sequence: state.attempt.sequence },
            sourceArtifact,
            sourceFindingFingerprints: [...fingerprints],
          });
        }
        ctx.flowManager.completeRequirementTestLifecycle({
          specId,
          decision,
          commandResult: result,
          deferredReceipt,
          findingsPublication,
          artifactWrites: failureArtifact === null ? [] : [failureArtifact.artifactWrite(gateResult.toJSON())],
        });
        ctx.flowState = ctx.flowManager.loadReadOnly(specId);
        return decision;
      },
    },
    "test-result-review": {
      helpKey: "flow.run.test-result-review",
      failureOwnership: DefinitionFailureOwnership.dispatcherPrimary(),
      runtimeLog: { stepId: "test-result-review" },
      command: () => import("./lib/run-test-result-review.js"),
      args: { flags: FLOW_TARGET_GUARD_FLAGS, options: [...FLOW_RUN_OPTIONS] },
      help: [
        "Usage: sennel flow run test-result-review",
        "",
        "Verify the cataloged test.execute attempt against transient raw output and code.",
        "Publishes the review history as steps/test-result-review/result.json; derived Markdown is not persisted.",
      ].join("\n"),
      async post(ctx, result) {
        const { attachedCanonicalCommandResultArtifact } = await import("./lib/canonical-command-result.js");
        const { validateTestResultReview } = await import("./lib/test-artifacts.js");
        const attached = attachedCanonicalCommandResultArtifact(result);
        if (attached?.logicalKey !== "test.result.review") throw new Error("test-result-review canonical result artifact is missing");
        validateTestResultReview(attached.payload);
        await applyTestChainTransition(ctx, result, "test-result-review");
      },
    },
    // retro is a mainline impl-phase step that aggregates test-execute results.
    retro: {
      helpKey: "flow.run.retro",
      failureOwnership: DefinitionFailureOwnership.dispatcherPrimary(),
      runtimeLog: { stepId: "retro" },
      command: () => import("./lib/run-retro.js"),
      args: { flags: withTargetGuardFlags(["--dry-run"]), options: [...FLOW_RUN_OPTIONS] },
      help: [
        "Usage: sennel flow run retro [options]",
        "",
        "Aggregate cataloged test execution and result-review attempts per requirement.",
        "Publishes steps/impl/retro/result.json; does not execute tests.",
        "",
        "Options:",
        "  --dry-run   Preview only, do not publish the attempt result",
      ].join("\n"),
      post(ctx, result) {
        if (
          result?.result === "recovered"
          && result?.artifacts?.evidenceRefresh?.recovered === true
        ) return;
        if (ctx.flowState?.policy?.nonblocking?.enabled === true) {
          const artifact = attachedCanonicalCommandResultPublications(result)
            .find((publication) => publication.logicalKey === "retro")?.payload ?? null;
          if (Number(artifact?.summary?.not_done || 0) > 0) return;
        }
        tryUpdateStepStatus(ctx, "retro", "done", undefined, { event: "retro:post", result });
      },
      async nonblockingPost(ctx, result) {
        const { recordEligibleNonblockingAttempt } = await import("./lib/nonblocking.js");
        recordEligibleNonblockingAttempt(ctx, "retro", result);
      },
    },
    "final-regression": {
      helpKey: "flow.run.final-regression",
      failureOwnership: DefinitionFailureOwnership.commandPrimaryWithDispatcherFallback(),
      runtimeLog: { stepId: "final-regression" },
      command: () => import("./lib/run-final-regression.js"),
      args: {
        flags: withTargetGuardFlags(["--record-and-proceed"]),
        options: ["--record-category", "--record-evidence", "--remaining-risk", ...FLOW_RUN_OPTIONS],
      },
      help: [
        "Usage: sennel flow run final-regression [--record-and-proceed --record-category <category> --record-evidence <text> --remaining-risk <text>]",
        "",
        "Run the full project-level regression command after retro and before finalize.",
        "Publishes steps/final-regression/result.json and transient attempt logs through the active Version Store.",
        "A current-diff failure may be recorded only as out_of_scope with explicit evidence and remaining risk.",
      ].join("\n"),
      async post(ctx, result) {
        if (
          result?.result === "recovered"
          && result?.artifacts?.evidenceRefresh?.recovered === true
        ) return;
        const { attachedCanonicalCommandResultArtifact } = await import("./lib/canonical-command-result.js");
        const { CanonicalTestArtifactStore } = await import("./lib/canonical-test-artifacts.js");
        const { captureFinalRegressionChangedSnapshotDigest, resolveCanonicalFinalRegressionTransition } = await import("./lib/final-regression-transition-facts.js");
        const { applyFinalRegressionTransition } = await import("./lib/final-regression-transition-application.js");
        const attached = attachedCanonicalCommandResultArtifact(result);
        if (attached?.logicalKey !== "final.regression") throw new Error("final-regression canonical result artifact is missing");
        const specId = ctx.specId ?? ctx.flowState.specId;
        // Explicit acceptance is a Definition-selected replacement Attempt.
        // The producer merely publishes the evidence; this plan adapter owns
        // the canonical settlement and must not reinterpret artifact fields.
        if (result?.failedRecorded !== true) {
          ctx.flowManager.publishCurrentAttemptResult({ specId, commandResult: result });
        }
        const state = ctx.flowManager.canonicalState(specId);
        const store = new CanonicalTestArtifactStore({ flowManager: ctx.flowManager, state });
        const decision = resolveCanonicalFinalRegressionTransition({
          flowManager: ctx.flowManager, specId,
          changedFileSnapshotDigest: () => captureFinalRegressionChangedSnapshotDigest({
            root: ctx.executionRoot || ctx.root,
            relativeSpecFile: store.location.relativeSpecFile,
          }),
          candidateArtifact: result?.failedRecorded === true ? attached.payload : null,
        });
        applyFinalRegressionTransition({
          flowManager: ctx.flowManager,
          specId,
          commandResult: result,
          decision,
        });
      },
      async nonblockingPost(ctx, result) {
        const { recordEligibleNonblockingAttempt } = await import("./lib/nonblocking.js");
        recordEligibleNonblockingAttempt(ctx, "final-regression", result);
      },
    },
    "acceptance-review": {
      helpKey: "flow.run.acceptance-review",
      failureOwnership: DefinitionFailureOwnership.commandPrimaryWithDispatcherFallback(),
      runtimeLog: { stepId: "acceptance-review" },
      command: () => import("./lib/run-acceptance-review.js"),
      args: { flags: FLOW_TARGET_GUARD_FLAGS, options: [...FLOW_RUN_OPTIONS] },
      help: [
        "Usage: sennel flow run acceptance-review",
        "",
        "Evaluate original request satisfaction after retro and before final-regression.",
        "Publishes steps/acceptance-review/result.json through the active Version Store and routes pass/non-pass verdicts.",
      ].join("\n"),
      async post(ctx, result) {
        const { attachedCanonicalCommandResultArtifact } = await import("./lib/canonical-command-result.js");
        const { validateAcceptanceReviewArtifact } = await import("./lib/acceptance-review-artifacts.js");
        const { resolveDefinitionRoute } = await import("./definition.js");
        const { acceptanceReviewRouteFacts } = await import("./lib/definition-route-facts.js");
        const attached = attachedCanonicalCommandResultArtifact(result);
        if (attached?.logicalKey !== "acceptance.review") {
          throw new Error("acceptance-review canonical result artifact is missing");
        }
        const spec = ctx.flowManager.readArtifact({
          specId: ctx.flowState.specId,
          logicalKey: "spec.record",
          consumerNodeId: "acceptance-review",
        });
        const requirementIds = JSON.parse(spec.bytes.toString("utf8")).requirements
          .map((entry) => entry.id);
        const artifact = validateAcceptanceReviewArtifact(attached.payload, { requirementIds });
        const specId = ctx.flowState.specId;
        const plan = resolveDefinitionRoute(acceptanceReviewRouteFacts({
          state: ctx.flowManager.canonicalState(specId),
          artifact,
        }));
        plan.apply({
          blocked() {
            ctx.flowManager.publishCurrentAttemptResult({ specId, commandResult: result });
          },
          repairAcceptanceToImplTriage() {
            // One Store Activity retains the reviewed artifact and creates
            // the replacement impl-triage Attempt together.
            ctx.flowManager.repairAcceptanceReview({ specId, commandResult: result });
          },
          awaitAcceptanceDecision() {
            tryUpdateStepStatus(ctx, "acceptance-review", "done", undefined, { event: "acceptance-review:post", result });
            ctx.flowManager.updateStepStatus({ stepId: "acceptance-decision", requestedStatus: "in_progress" }, { specId });
          },
          advanceFinalRegression() {
            tryUpdateStepStatus(ctx, "acceptance-review", "done", undefined, { event: "acceptance-review:post", result });
            ctx.flowManager.completeAcceptanceDecisionNoOp({ specId });
            ctx.flowManager.updateStepStatus({ stepId: "final-regression", requestedStatus: "in_progress" }, { specId });
          },
        });
        ctx.flowState = ctx.flowManager.load(specId);
      },
    },
    // report generates a work report from the current flow state.
    report: {
      helpKey: "flow.run.report",
      failureOwnership: DefinitionFailureOwnership.lifecycleOutbox(),
      runtimeLog: { stepId: "report" },
      command: () => import("./lib/run-report.js"),
      args: { flags: withTargetGuardFlags(["--dry-run"]), options: [...FLOW_RUN_OPTIONS] },
      help: [
        "Usage: sennel flow run report [options]",
        "",
        "Generate a work report from the current flow state.",
        "",
        "Options:",
        "  --dry-run   Preview only, do not write report.json",
      ].join("\n"),
      async pre(ctx) {
        await applyLifecycleActionsFromRegistry(ctx, {
          event: "report:pre",
          command: "report",
        });
      },
      async post(ctx, result) {
        await applyLifecycleActionsFromRegistry(ctx, {
          event: "report:post",
          command: "report",
        }, result);
      },
      async onError(ctx, err) {
        await applyLifecycleActionsFromRegistry(ctx, {
          event: "report:onError",
          command: "report",
        }, null, err);
      },
    },
  },
  report: {
    show: {
      helpKey: "flow.report.show",
      runtimeLog: { stepMetadata: false },
      command: () => import("./lib/run-report-show.js"),
      requiresFlow: false,
      args: { flags: [] },
      help: [
        "Usage: sennel flow report show",
        "",
        "Stream the most recent finalize Report text to stdout.",
        "Reads .sennel/last-finalized-spec to locate the latest",
        "finalized spec and prints its report.json `text` field.",
        "Exits non-zero if the pointer or report.json is missing.",
      ].join("\n"),
    },
  },
};

/**
 * tools/lib/cli.js
 *
 * repoRoot / parseArgs — 全エントリポイント共通の CLI ユーティリティ。
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { runCmd, assertOk } from "./process.js";
import { PRODUCT } from "./product.js";

/**
 * sennel パッケージの src/ ディレクトリの絶対パス。
 * lib/ から1階層上が src/ であることを利用して解決する。
 */
export const PKG_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

/**
 * 作業ルートを返す。
 * SENNEL_WORK_ROOT 環境変数が設定されている場合はそれを使用する（プロジェクトモード）。
 * それ以外は git rev-parse でリポジトリルートを取得し、失敗時は process.cwd() を返す。
 *
 * @returns {string} 作業ルートの絶対パス
 */
export function repoRoot() {
  if (process.env[PRODUCT.env("WORK_ROOT")]) return process.env[PRODUCT.env("WORK_ROOT")];
  // Logger 基盤の依存元のため runCmd を直接使う。runGit に変更してはならない
  // （Logger.git → resolveLogDir → repoRoot → runGit → Logger.git で無限再帰になる）。
  const res = runCmd("git", ["rev-parse", "--show-toplevel"]);
  if (res.ok) return res.stdout.trim();
  // npm パッケージとしてインストールされた場合、相対パス推定は
  // node_modules/ 内部を指すため process.cwd() を使用する
  return process.cwd();
}

/**
 * ソースルートを返す。
 * SENNEL_SOURCE_ROOT 環境変数が設定されている場合はそれを使用する（プロジェクトモード）。
 * それ以外は repoRoot() と同じ値を返す。
 *
 * @returns {string} ソースルートの絶対パス
 */
export function sourceRoot() {
  if (process.env[PRODUCT.env("SOURCE_ROOT")]) return process.env[PRODUCT.env("SOURCE_ROOT")];
  return repoRoot();
}

/**
 * 汎用 CLI パーサー。
 *
 * @param {string[]} argv - process.argv.slice(2)
 * @param {Object}   spec
 * @param {string[]} [spec.flags]    - ブール型フラグ (例: ["--dry-run","--force"])
 * @param {string[]} [spec.options]  - 値付きオプション (例: ["--type","--agent"])
 * @param {string[]} [spec.optionalOptions] - 任意の値を取るオプション (例: ["--reset"])
 * @param {Object}   [spec.aliases]  - 短縮名マップ (例: { "-v": "--verbose" })
 * @param {Object}   [spec.defaults] - デフォルト値
 * @returns {Object} パース済みオプション (help は常に含む)
 */
export function parseArgs(argv, spec) {
  const flags = new Set(spec.flags || []);
  const options = new Set(spec.options || []);
  const optionalOptions = new Set(spec.optionalOptions || []);
  const aliases = spec.aliases || {};
  const opts = { ...spec.defaults, help: false };

  for (let i = 0; i < argv.length; i += 1) {
    let a = argv[i];
    if (a === "--") continue;
    if (a in aliases) a = aliases[a];
    if (a === "-h" || a === "--help") { opts.help = true; continue; }
    if (flags.has(a)) {
      opts[flagKey(a)] = true;
      continue;
    }
    if (options.has(a)) {
      const value = argv[i + 1];
      if (value == null || String(value).trim() === "" || String(value).startsWith("-")) {
        throw new Error(`Missing value for option: ${a}`);
      }
      opts[flagKey(a)] = String(value).trim();
      i += 1;
      continue;
    }
    if (optionalOptions.has(a)) {
      const value = argv[i + 1];
      if (value != null && String(value).trim() !== "" && !String(value).startsWith("-")) {
        opts[flagKey(a)] = String(value).trim();
        i += 1;
      } else {
        opts[flagKey(a)] = true;
      }
      continue;
    }
    throw new Error(`Unknown option: ${a}`);
  }
  return opts;
}

/**
 * worktree 内で実行されているかを判定する。
 * git worktree では .git がディレクトリではなく `gitdir: ...` を含むファイルになる。
 *
 * @param {string} root - リポジトリルートパス
 * @returns {boolean}
 */
export function isInsideWorktree(root) {
  const dotGit = path.join(root, ".git");
  try {
    return fs.statSync(dotGit).isFile();
  } catch (_) {
    return false;
  }
}

/**
 * worktree からメインリポジトリのパスを取得する。
 * `git rev-parse --git-common-dir` で共有 .git ディレクトリを取得し、その親を返す。
 *
 * @param {string} root - リポジトリルートパス
 * @returns {string} メインリポジトリの絶対パス
 */
export function getMainRepoPath(root) {
  // Logger 基盤の依存元のため runCmd を直接使う。runGit に変更してはならない
  // （Logger.git → resolveLogDir → getMainRepoPath → runGit → Logger.git で無限再帰になる）。
  const res = runCmd("git", ["-C", root, "rev-parse", "--git-common-dir"]);
  if (!res.ok && !(res.status === 0 && res.stdout.trim())) {
    assertOk(res, "failed to resolve git-common-dir");
  }
  const gitCommonDir = res.stdout.trim();
  // git-common-dir は絶対パスまたは root からの相対パスを返す
  const abs = path.resolve(root, gitCommonDir);
  return path.dirname(abs);
}

/**
 * sennel パッケージのバージョン文字列を返す。
 * package.json の読み込みに失敗した場合は "?" を返す。
 *
 * @returns {string}
 */
export function getPackageVersion() {
  try {
    const pkg = JSON.parse(fs.readFileSync(path.join(PKG_DIR, "..", "package.json"), "utf8"));
    return pkg.version;
  } catch (_) {
    return "?";
  }
}

/**
 * UTC タイムスタンプ文字列を生成する。
 *
 * @param {Date} [date] - 日付オブジェクト（省略時は現在時刻）
 * @returns {string} "YYYY-MM-DD HH:MM:SS UTC"
 */
export function formatUTCTimestamp(date) {
  return (date || new Date()).toISOString().replace("T", " ").replace(/\.\d+Z$/, " UTC");
}

/** --some-flag → someFlag */
function flagKey(flag) {
  return flag.replace(/^--/, "").replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}

/**
 * Unified command definitions for executable dispatch and import-safe help
 * metadata. Help reads never invoke lazy handlers, because command modules
 * may have import-time side effects.
 */

import { fileURLToPath, pathToFileURL } from "node:url";
import { FLOW_COMMANDS } from "../flow/registry.js";

const COMMAND_NAME_RE = /^[a-z0-9][a-z0-9-]*$/;

export class CommandHelpMetadata {
  constructor({
    name,
    section = "",
    summary = "",
    usage = "",
    help = "",
    args = {},
    options = [],
    experimental = false,
    localeKey = null,
    locale = null,
    owner = "core-command-metadata",
    subcommands = [],
  }) {
    if (typeof name !== "string" || name.trim() === "") {
      throw new Error("command help metadata requires a non-empty name");
    }
    this.name = name;
    this.section = section;
    this.summary = summary;
    this.usage = usage || `Usage: sennel ${name}`;
    this.help = help;
    this.args = args && typeof args === "object" ? args : {};
    this.options = Array.isArray(options) ? options : [];
    this.experimental = Boolean(experimental);
    this.localeKey = localeKey || null;
    this.locale = locale || null;
    this.owner = owner;
    this.subcommands = subcommands.map((entry) => entry instanceof CommandHelpMetadata
      ? entry
      : new CommandHelpMetadata({ ...entry, owner }));
  }

  find(parts) {
    const [head, ...rest] = parts;
    if (!head) return this;
    const sub = this.subcommands.find((entry) => (
      entry.name.split(" ").at(-1) === head || entry.name === [this.name, head].join(" ")
    ));
    return rest.length === 0 ? sub : sub?.find(rest);
  }

  all() {
    return [this, ...this.subcommands.flatMap((entry) => entry.all())];
  }
}

export class CoreCommandMetadataRegistry {
  constructor(entries) {
    this.entries = [];
    const names = new Set();
    for (const entry of entries) {
      const metadata = entry instanceof CommandHelpMetadata ? entry : new CommandHelpMetadata(entry);
      if (names.has(metadata.name)) throw new Error(`duplicate command help metadata: ${metadata.name}`);
      names.add(metadata.name);
      this.entries.push(metadata);
    }
  }

  findCommand(parts) {
    const normalized = Array.isArray(parts) ? parts : String(parts).split(/\s+/);
    const [head, ...rest] = normalized;
    const top = this.entries.find((entry) => entry.name === head);
    if (!top) return null;
    return rest.length === 0 ? top : top.find(rest);
  }

  topLevelCommands() {
    return this.entries.flatMap((entry) => entry.subcommands.length ? entry.subcommands : [entry]);
  }

  allCommands() {
    return this.entries.flatMap((entry) => entry.all());
  }
}

export class CommandEntrypoint {
  constructor({ modulePath, invocation }) {
    if (typeof modulePath !== "string" || modulePath.trim() === "") {
      throw new Error("command entrypoint modulePath is required");
    }
    if (!new Set(["main", "script"]).has(invocation)) {
      throw new Error(`invalid command entrypoint invocation: ${invocation}`);
    }
    this.moduleUrl = new URL(modulePath, import.meta.url);
    this.modulePath = fileURLToPath(this.moduleUrl);
    this.invocation = invocation;
    Object.freeze(this);
  }

  async execute(args) {
    process.argv = [process.argv[0], this.modulePath, ...args];
    const mod = await import(pathToFileURL(this.modulePath).href);
    if (this.invocation === "script") return;
    if (typeof mod.main !== "function") {
      throw new Error(`command module does not export main(): ${this.modulePath}`);
    }
    await mod.main();
  }
}

function helpText({ usage, summary, options = [] }) {
  const lines = [usage, "", summary];
  if (options.length > 0) {
    lines.push("", "Options:", ...options.map((option) => `  ${option}`));
  }
  return lines.join("\n");
}

export class CommandDefinition {
  constructor({
    name,
    command = null,
    outputMode = null,
    passthroughArgs = false,
    args = null,
    help = {},
    subcommands = [],
    entrypoint = null,
    dispatch = {},
    allowInvalidConfig = false,
    routed = false,
  }) {
    if (typeof name !== "string" || !COMMAND_NAME_RE.test(name)) {
      throw new Error(`invalid command name: ${name}`);
    }
    if (command != null && typeof command !== "function") {
      throw new Error(`command handler must be a function: ${name}`);
    }
    if (command && outputMode !== "raw" && outputMode !== "envelope") {
      throw new Error(`command outputMode is required: ${name}`);
    }
    this.name = name;
    this.command = command;
    this.outputMode = outputMode;
    this.passthroughArgs = Boolean(passthroughArgs);
    this.args = args;
    this.helpConfig = Object.freeze({ ...(typeof help === "string" ? {} : help) });
    this.help = typeof help === "string"
      ? help
      : typeof help.text === "string"
        ? help.text
        : helpText({
            usage: help.usage || `Usage: sennel ${name}`,
            summary: help.summary || "",
            options: help.options || [],
          });
    this.entrypoint = entrypoint instanceof CommandEntrypoint
      ? entrypoint
      : entrypoint
        ? new CommandEntrypoint(entrypoint)
        : null;
    this.allowInvalidConfig = Boolean(allowInvalidConfig);
    this.routed = Boolean(routed);
    Object.assign(this, dispatch);

    this.subcommands = new Map();
    for (const child of subcommands) {
      if (!(child instanceof CommandDefinition)) throw new Error(`invalid subcommand under ${name}`);
      if (this.subcommands.has(child.name)) throw new Error(`duplicate command: ${name} ${child.name}`);
      this.subcommands.set(child.name, child);
    }
    if (!this.command && !this.entrypoint && this.subcommands.size === 0 && !this.routed) {
      throw new Error(`command definition has no handler or subcommands: ${name}`);
    }
  }

  find(parts) {
    if (parts.length === 0) return this;
    const [head, ...rest] = parts;
    return this.subcommands.get(head)?.find(rest) || null;
  }

  metadata(parentPath = []) {
    const path = [...parentPath, this.name];
    return new CommandHelpMetadata({
      name: path.join(" "),
      section: this.helpConfig.section || "",
      summary: this.helpConfig.summary || "",
      usage: this.helpConfig.usage || this.help.split(/\r?\n/, 1)[0],
      help: this.help,
      args: this.args || {},
      options: this.helpConfig.options || [],
      experimental: Boolean(this.helpConfig.experimental),
      localeKey: this.helpConfig.localeKey || null,
      locale: this.helpConfig.locale || null,
      owner: this.helpConfig.owner || "core-command-metadata",
      subcommands: [...this.subcommands.values()].map((child) => child.metadata(path)),
    });
  }

  paths(parentPath = []) {
    const path = [...parentPath, this.name];
    return [path.join(" "), ...[...this.subcommands.values()].flatMap((child) => child.paths(path))];
  }

  renderHelp() {
    if (this.subcommands.size === 0) return this.help;
    const lines = [this.help, "", "Subcommands:"];
    for (const child of this.subcommands.values()) {
      lines.push(`  ${child.name.padEnd(14)}${child.helpConfig.summary || ""}`.trimEnd());
    }
    return lines.join("\n");
  }

  dispatchChildren() {
    return Object.fromEntries([...this.subcommands.values()].map((child) => [
      child.name,
      child.command || child.entrypoint ? child : child.dispatchChildren(),
    ]));
  }
}

export class CommandRegistry {
  constructor(definitions = []) {
    this.definitions = new Map();
    for (const definition of definitions) this.register(definition);
  }

  register(definition) {
    if (!(definition instanceof CommandDefinition)) throw new Error("CommandDefinition is required");
    if (this.definitions.has(definition.name)) throw new Error(`duplicate command: ${definition.name}`);
    this.definitions.set(definition.name, definition);
    return definition;
  }

  find(parts) {
    const normalized = Array.isArray(parts) ? parts : String(parts).trim().split(/\s+/);
    const [head, ...rest] = normalized;
    if (!head) return null;
    return this.definitions.get(head)?.find(rest) || null;
  }

  routePaths() {
    return [...this.definitions.values()].flatMap((definition) => definition.paths()).sort();
  }

  helpPaths() {
    return this.metadataRegistry().allCommands().map((entry) => entry.name).sort();
  }

  metadataRegistry() {
    return new CoreCommandMetadataRegistry(
      [...this.definitions.values()].map((definition) => definition.metadata()),
    );
  }
}

function rawDefinition(name, modulePath, help, { args = null, passthroughArgs = true } = {}) {
  return new CommandDefinition({
    name,
    command: () => import(modulePath),
    outputMode: "raw",
    passthroughArgs,
    args,
    help,
  });
}

